    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "There is limited evidence to evaluate the sustainability of evidence-based interventions (EBIs) for healthcare improvement. Discussion: It is unclear which approach/approaches are most effective for evaluating sustainability and what measures and outcomes are most commonly used.",
      "reason": "The abstract states the current state is limited evidence and highlights an important uncertainty about which approaches/measures/outcomes are most effective."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Our review offers methodological recommendations for sustainability evaluation research and highlights the importance in understanding mechanisms of sustainability to advance the field.",
      "reason": "The abstract provides a clear reason to conduct the review, including advancing methodological recommendations and the need to understand mechanisms to improve the field."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research. In a review by Lennox et al., they indicated that only 21% of studies reported any information on sustainability outcomes [6].",
      "reason": "The evidence references prior syntheses (e.g., Lennox et al.) and positions the current review as different from recent syntheses, but it does not clearly explain the need for a current review in terms of specific updates/replications with full citation details within a rationale section."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No passage describes the proposed mechanism of action of the intervention as part of the review rationale."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No logic model or hypothesised relationships between intervention components and outcomes are reported in the available evidence."
    }
  ],
  "confidence": 62
