    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "The aim of this integrative review was to identify and synthesize approaches that have been used to evaluate the sustainability of EBIs in healthcare. We aimed to enhance our understanding of sustainability definitions, research designs, data collection methods, timing, measures, and sustainability outcomes used for sustainability evaluation studies.",
      "reason": "The review objective(s) are explicitly stated (aims to identify/synthesize approaches and enhance understanding of related elements). However, the evidence does not show that the objectives/questions are formulated using a relevant question-formulation framework (e.g., explicit framework-based phrasing)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_6",
      "quote": "The aim of this integrative review was to identify and synthesize approaches that have been used to evaluate the sustainability of EBIs in healthcare.",
      "reason": "This is an integrative review of approaches for evaluating sustainability (not a review of intervention effects with planned comparisons). Therefore, a PICO-style planned comparison requirement does not apply."
    }
  ],
  "confidence": 78
}

